fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // If there are 0 or 1 characters, they are trivially all the same.
    if char_arr.len() <= 1 {
        return true;
    }

    // Compare every character after the first to the first character.
    let first = char_arr[0];
    for &ch in &char_arr[1..] {
        if ch != first {
            return false;
        }
    }
    true
}

